1	import { Component } from "../components/Component.js";
2	import { WHY_SKILL_PREVIEW } from "../config/component.config.js";
3	import type { WhySkillPreviewOptions } from "../types/component.types.js";
4	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
5	
6	interface WhySkillBinding {
7	  item: HTMLElement;
8	  onEnter: () => void;
9	  onLeave: () => void;
10	}
11	
12	export class WhySkillPreview extends Component {
13	  private readonly list: HTMLElement;
14	  private readonly preview: HTMLElement;
15	  private readonly video: HTMLVideoElement;
16	  private readonly itemSelector: string;
17	  private readonly videoDataAttr: string;
18	  private readonly bindings: WhySkillBinding[] = [];
19	  private hideTimer: number | null = null;
20	  private switchTimer: number | null = null;
21	  private isSwitching = false;
22	  private pendingItem: HTMLElement | null = null;
23	  private pendingSrc: string | null = null;
24	  private currentItem: HTMLElement | null = null;
25	
26	  constructor(
27	    list: HTMLElement,
28	    preview: HTMLElement,
29	    video: HTMLVideoElement,
30	    itemSelector: string,
31	    videoDataAttr: string,
32	  ) {
33	    super();
34	    this.list = list;
35	    this.preview = preview;
36	    this.video = video;
37	    this.itemSelector = itemSelector;
38	    this.videoDataAttr = videoDataAttr;
39	  }
40	
41	  static init(options: WhySkillPreviewOptions = {}): void {
42	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
43	    if (!responsive.flags.hoverCapable) return;
44	
45	    const listSelector = options.listSelector ?? WHY_SKILL_PREVIEW.listSelector;
46	    const itemSelector = options.itemSelector ?? WHY_SKILL_PREVIEW.itemSelector;
47	    const previewSelector =
48	      options.previewSelector ?? WHY_SKILL_PREVIEW.previewSelector;
49	
50	    const list = document.querySelector<HTMLElement>(listSelector);
51	    const preview = document.querySelector<HTMLElement>(previewSelector);
52	    const video = preview?.querySelector<HTMLVideoElement>(
53	      WHY_SKILL_PREVIEW.videoSelector,
54	    );
55	    if (!list || !preview || !video) return;
56	
57	    const instance = new WhySkillPreview(
58	      list,
59	      preview,
60	      video,
61	      itemSelector,
62	      WHY_SKILL_PREVIEW.videoDataAttr,
63	    );
64	    instance.init();
65	  }
66	
67	  protected mount(): void {
68	    const items = Array.from(
69	      this.list.querySelectorAll<HTMLElement>(this.itemSelector),
70	    );
71	    if (items.length === 0) return;
72	    items.forEach((item) => this._bindItem(item));
73	  }
74	
75	  protected applyVisibility(visible: boolean): void {
76	    this.preview.setAttribute("aria-hidden", visible ? "false" : "true");
77	    this.preview.classList.toggle(WHY_SKILL_PREVIEW.visibleClass, visible);
78	  }
79	
80	  getVisibleState(): boolean {
81	    return this.preview.classList.contains(WHY_SKILL_PREVIEW.visibleClass);
82	  }
83	
84	  override dispose(): void {
85	    this._clearHideTimer();
86	    this._clearSwitchTimer();
87	    this._pauseVideo();
88	    this.bindings.forEach((binding) => {
89	      binding.item.removeEventListener("mouseenter", binding.onEnter);
90	      binding.item.removeEventListener("mouseleave", binding.onLeave);
91	      delete binding.item.dataset[WHY_SKILL_PREVIEW.boundFlag];
92	    });
93	    this.bindings.length = 0;
94	    super.dispose();
95	  }
96	
97	  private _bindItem(item: HTMLElement): void {
98	    if (item.dataset[WHY_SKILL_PREVIEW.boundFlag] === "true") return;
99	    const binding: WhySkillBinding = {
100	      item,
101	      onEnter: () => this._onEnter(item),
102	      onLeave: () => this._scheduleHide(),
103	    };
104	    item.dataset[WHY_SKILL_PREVIEW.boundFlag] = "true";
105	    item.addEventListener("mouseenter", binding.onEnter);
106	    item.addEventListener("mouseleave", binding.onLeave);
107	    this.bindings.push(binding);
108	  }
109	
110	  private _onEnter(item: HTMLElement): void {
111	    this._clearHideTimer();
112	    this.preview.classList.remove(WHY_SKILL_PREVIEW.closingClass);
113	
114	    const videoSrc = item.getAttribute(this.videoDataAttr);
115	    if (!videoSrc) return;
116	
117	    const isSameItem = this.currentItem === item;
118	    if (isSameItem) return;
119	
120	    if (this.getVisibleState()) {
121	      // 이미 다른 스킬이 열려있음 — cinematic switch
122	      if (this.isSwitching) {
123	        this.pendingItem = item;
124	        this.pendingSrc = videoSrc;
125	        return;
126	      }
127	      this._startSwitch(item, videoSrc);
128	    } else {
129	      this._pauseVideo();
130	      this.video.src = videoSrc;
131	      this.video.load();
132	      this.currentItem = item;
133	      this._updatePosition(item);
134	      this._show();
135	      this.video.play().catch(() => {/* autoplay policy — silent */});
136	    }
137	  }
138	
139	  private _updatePosition(item: HTMLElement): void {
140	    const rect = item.getBoundingClientRect();
141	    const centerY = rect.top + rect.height / 2;
142	    this.preview.style.top = `${centerY}px`;
143	  }
144	
145	  private _startSwitch(item: HTMLElement, videoSrc: string): void {
146	    this.isSwitching = true;
147	    this.preview.classList.add(WHY_SKILL_PREVIEW.switchingClass);
148	
149	    this.switchTimer = window.setTimeout(() => {
150	      this._pauseVideo();
151	      this.video.src = videoSrc;
152	      this.video.load();
153	      this.currentItem = item;
154	      this._updatePosition(item);
155	
156	      this.preview.classList.remove(WHY_SKILL_PREVIEW.switchingClass);
157	      this.video.play().catch(() => {/* autoplay policy — silent */});
158	
159	      this.isSwitching = false;
160	      this.switchTimer = null;
161	
162	      if (this.pendingItem !== null && this.pendingSrc !== null) {
163	        const nextItem = this.pendingItem;
164	        const nextSrc = this.pendingSrc;
165	        this.pendingItem = null;
166	        this.pendingSrc = null;
167	        if (nextItem !== this.currentItem) {
168	          this._startSwitch(nextItem, nextSrc);
169	        }
170	      }
171	    }, WHY_SKILL_PREVIEW.switchAnimMs);
172	  }
173	
174	  private _scheduleHide(): void {
175	    this._clearHideTimer();
176	    this.hideTimer = window.setTimeout(() => {
177	      this._startClosing();
178	      window.setTimeout(() => {
179	        this.preview.classList.remove(WHY_SKILL_PREVIEW.closingClass);
180	      }, WHY_SKILL_PREVIEW.closeAnimationMs);
181	      this.currentItem = null;
182	      this.hideTimer = null;
183	    }, WHY_SKILL_PREVIEW.closeDelayMs);
184	  }
185	
186	  private _startClosing(): void {
187	    this._pauseVideo();
188	    this._hide();
189	    this.preview.classList.add(WHY_SKILL_PREVIEW.closingClass);
190	  }
191	
192	  private _show(): void {
193	    this.setVisibleOn();
194	  }
195	
196	  private _hide(): void {
197	    this.setVisibleOff();
198	  }
199	
200	  private _pauseVideo(): void {
201	    if (!this.video.paused) this.video.pause();
202	  }
203	
204	  private _clearHideTimer(): void {
205	    if (this.hideTimer === null) return;
206	    window.clearTimeout(this.hideTimer);
207	    this.hideTimer = null;
208	  }
209	
210	  private _clearSwitchTimer(): void {
211	    if (this.switchTimer === null) return;
212	    window.clearTimeout(this.switchTimer);
213	    this.switchTimer = null;
214	    this.isSwitching = false;
215	    this.pendingItem = null;
216	    this.pendingSrc = null;
217	  }
218	}
